diff --git a/client.mjs b/client.mjs
index 9ad81d0..5d5c631 100644
--- a/client.mjs
+++ b/client.mjs
@@ -1,0 +2 @@
+import { sleep as realSleep } from './util.mjs';
@@ -12,4 +13,23 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep, maxRetries = 3 } = {}) {
+  let lastError;
+  for (let attempt = 0; attempt <= maxRetries; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        const err = new HttpError(res.status, url);
+        // Don't retry 4xx errors
+        if (res.status >= 400 && res.status < 500) throw err;
+        lastError = err;
+        if (attempt < maxRetries) await sleep(100 * Math.pow(2, attempt));
+        continue;
+      }
+      return res.json();
+    } catch (err) {
+      // Don't retry 4xx errors
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) throw err;
+      // Network errors (fetch threw) can be retried
+      lastError = err;
+      if (attempt < maxRetries) await sleep(100 * Math.pow(2, attempt));
+    }
+  }
+  throw lastError;
