diff --git a/client.mjs b/client.mjs
index 9ad81d0..09222d2 100644
--- a/client.mjs
+++ b/client.mjs
@@ -2,0 +3,2 @@
+import { sleep as realSleep } from './util.mjs';
+
@@ -12,4 +14,29 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  let lastError;
+  
+  for (let attempt = 0; attempt < 3; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        const err = new HttpError(res.status, url);
+        // Don't retry on 4xx errors
+        if (res.status >= 400 && res.status < 500) throw err;
+        // Retry on 5xx (e.g., 503)
+        lastError = err;
+        if (attempt < 2) await sleep(100 * Math.pow(2, attempt));
+        continue;
+      }
+      return res.json();
+    } catch (err) {
+      lastError = err;
+      // Retry on network errors (TypeError for connection drops)
+      if (err instanceof TypeError && attempt < 2) {
+        await sleep(100 * Math.pow(2, attempt));
+        continue;
+      }
+      // Don't retry HttpError for 4xx or any other error types
+      throw err;
+    }
+  }
+  
+  throw lastError;
