@@ -2,0 +3,2 @@
+import { sleep as realSleep } from './util.mjs';
+
@@ -12,4 +14,28 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  const maxRetries = 3;
+  let lastError;
+
+  for (let attempt = 0; attempt <= maxRetries; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) throw new HttpError(res.status, url);
+      return res.json();
+    } catch (err) {
+      lastError = err;
+
+      // Don't retry 4xx errors
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) {
+        throw err;
+      }
+
+      // If this was the last attempt, throw the error
+      if (attempt === maxRetries) {
+        throw err;
+      }
+
+      // Short backoff before retrying (exponential: 100ms, 200ms, 400ms)
+      await sleep(100 * Math.pow(2, attempt));
+    }
+  }
+
+  throw lastError;
