+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  const maxAttempts = 3;
+  let lastError;
+
+  for (let attempt = 0; attempt < maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        const err = new HttpError(res.status, url);
+        // Don't retry 4xx errors; throw immediately
+        if (res.status >= 400 && res.status < 500) {
+          throw err;
+        }
+        // For 5xx and other non-ok errors, may retry
+        lastError = err;
+        if (attempt < maxAttempts - 1) {
+          const backoffMs = Math.pow(2, attempt) * 100; // 100ms, 200ms, 400ms
+          await sleep(backoffMs);
+        }
+      } else {
+        return res.json();
+      }
+    } catch (err) {
+      // 4xx HttpErrors should be rethrown immediately
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) {
+        throw err;
+      }
+      // For other errors (5xx or network), may retry
+      lastError = err;
+      if (attempt < maxAttempts - 1) {
+        const backoffMs = Math.pow(2, attempt) * 100;
+        await sleep(backoffMs);
+      }
+    }
+  }
+
+  // Exhausted all retries
+  throw lastError;
